{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "In CD-1 mice, compound 22a, a primary-amide/fluorophenyl pyrrolidine analog, crossed the BBB with a plasma-to-brain ratio of about 2:1, directly supporting CNS access for the query's amide/fluorophenyl/basic-amine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "The enantiomeric analog 22b also showed approximately 2:1 plasma-to-brain distribution in mice, independently confirming that this chemotype achieves meaningful brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "[11C]LY2795050, a primary-amide/fluorophenyl pyrrolidine KOR antagonist structurally similar to the query, showed favorable brain uptake in human clinical PET studies, supporting meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "18F-LY2459989 exhibited high brain uptake in nonhuman primates with favorable pharmacokinetics, providing strong in vivo evidence that this amide/fluorophenyl/basic-amine class penetrates the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "A simple primary-amide pyridine analog achieved a brain concentration of 3180 ng/g after oral dosing in rats, supporting the CNS-penetrant behavior of amide-containing heteroaromatic compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Peposertib showed restricted free brain distribution (Kp,uu,brain 5%) in mice, but its larger morpholine-containing scaffold and transporter-prone profile are not shared by the query, so this contradictory evidence is outweighed.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C01"],
      "claim": "Neferine showed little brain distribution in rats, but as a large bisbenzylisoquinoline with a very different physicochemical and transporter profile, it is a weak contradictory anchor for the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query's primary-amide/fluorophenyl/basic-amine CNS scaffold is supported by multiple close analogs with measured brain penetration in mice, nonhuman primates, and humans. The physicochemical prior is borderline but not disqualifying, and the contradictory restricted-CNS records involve structurally distinct, larger, transporter-prone molecules. Overall, meaningful CNS access is predicted.",
  "evidence_gaps": [
    "No direct Kp,uu,brain or human PET data for the exact query molecule.",
    "Transporter phenotype (P-gp/BCRP) of the query is not experimentally defined.",
    "Borderline TPSA and molecular weight may reduce passive permeability but do not preclude meaningful CNS access."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

